glsl3.frag:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec4 color;
in vec2 uv0;
layout(std140) uniform Constant {
  vec4 brighterColor;
  vec4 middleColor;
  vec4 darkerColor;
  vec2 noiseScale;
  float bodyWidth;
  float bodyHeight;
  float cornerRadius;
  float flameHeight;
  float edgeRoughness;
  float bandSpacing;
  float fireSpeed;
  float energy;
};
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}
float noise(vec2 p) {
  vec2 cell = floor(p);
  vec2 local = fract(p);
  local = local * local * (3.0 - 2.0 * local);
  float a = hash(cell);
  float b = hash(cell + vec2(1.0, 0.0));
  float c = hash(cell + vec2(0.0, 1.0));
  float d = hash(cell + vec2(1.0, 1.0));
  return mix(mix(a, b, local.x), mix(c, d, local.x), local.y);
}
float fbm(vec2 p) {
  float value = 0.0;
  float amplitude = 0.56;
  for (int octave = 0; octave < 4; octave++) {
    value += amplitude * noise(p);
    p = p * 2.03 + vec2(9.7, 4.3);
    amplitude *= 0.5;
  }
  return value;
}
float roundedBoxSdf(vec2 p, vec2 halfSize, float radius) {
  float safeRadius = max(0.001, min(radius, min(halfSize.x, halfSize.y)));
  vec2 q = abs(p) - halfSize + vec2(safeRadius);
  return min(max(q.x, q.y), 0.0) + length(max(q, vec2(0.0))) - safeRadius;
}
float movingFireNoise(vec2 p, float time) {
  float broad = fbm(vec2(
    p.x * noiseScale.x + sin(time * 0.63) * 0.18,
    p.y * noiseScale.y - time * 1.05
  ));
  float curl = fbm(vec2(
    p.x * noiseScale.x * 0.72 + (broad - 0.5) * 1.05,
    p.y * noiseScale.y * 0.78 - time * 0.68
  ));
  float fine = noise(vec2(
    p.x * noiseScale.x * 2.15 + curl * 0.82,
    p.y * noiseScale.y * 1.95 - time * 1.55
  ));
  return clamp(broad * 0.68 + curl * 0.24 + fine * 0.08, 0.0, 1.0);
}
float fireGradient(vec2 p, float visualEnergy, float noiseValue) {
  float halfWidth = bodyWidth * (0.96 + visualEnergy * 0.04);
  float halfHeight = bodyHeight + flameHeight * (0.62 + visualEnergy * 0.16);
  vec2 center = vec2(0.0, -0.1 + visualEnergy * 0.025);
  float xRatio = clamp(abs(p.x) / max(0.001, halfWidth), 0.0, 1.0);
  float bottomWeight = 1.0 - smoothstep(center.y - 0.08, center.y + 0.1, p.y);
  float topWeight = smoothstep(center.y + halfHeight * 0.04, center.y + halfHeight, p.y);
  vec2 curvedP = p - center;
  curvedP.y -= bottomWeight * xRatio * xRatio * 0.11;
  curvedP.y -= topWeight * (1.0 - noiseValue) * (0.5 + visualEnergy * 0.12);
  float distanceToBounds = roundedBoxSdf(curvedP, vec2(halfWidth, halfHeight), cornerRadius);
  distanceToBounds += (noiseValue - 0.5) * edgeRoughness * 0.62;
  float localY = clamp((p.y - (center.y - halfHeight)) / max(0.001, halfHeight * 2.0), 0.0, 1.0);
  float verticalHeat = 1.16 - localY * (0.86 - visualEnergy * 0.08);
  verticalHeat += topWeight * (1.0 - noiseValue) * (1.0 - noiseValue) * 0.28;
  float boundaryLoss = smoothstep(-edgeRoughness, edgeRoughness * 0.72, distanceToBounds);
  return verticalHeat - boundaryLoss * 0.84 + visualEnergy * 0.055;
}
vec4 frag () {
  vec2 p = vec2(uv0.x - 0.5, 0.5 - uv0.y) * 2.0;
  float visualEnergy = clamp(energy, 0.0, 1.0);
  float time = cc_time.x * fireSpeed * (1.0 + visualEnergy * 0.55);
  float noiseValue = movingFireNoise(p, time);
  float gradient = fireGradient(p, visualEnergy, noiseValue);
  float outer = step(noiseValue, gradient);
  float middle = step(noiseValue, gradient - bandSpacing * 0.65) * outer;
  float bright = step(noiseValue, gradient - bandSpacing * 2.1) * middle;
  vec3 rgb = darkerColor.rgb;
  rgb = mix(rgb, middleColor.rgb, middle);
  rgb = mix(rgb, brighterColor.rgb, bright);
  return vec4(rgb * color.rgb, outer);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

